class Solution { public List<Integer> eventualSafeNodes(int[][] g) { int n=g.length;List<Integer>[]r=new List[n];for(int i=0;i<n;i++)r[i]=new ArrayList<>();int[]d=new int[n];for(int u=0;u<n;u++){d[u]=g[u].length;for(int v:g[u])r[v].add(u);}ArrayDeque<Integer>q=new ArrayDeque<>();for(int i=0;i<n;i++)if(d[i]==0)q.add(i);boolean[]s=new boolean[n];while(!q.isEmpty()){int v=q.remove();s[v]=true;for(int u:r[v])if(--d[u]==0)q.add(u);}List<Integer>out=new ArrayList<>();for(int i=0;i<n;i++)if(s[i])out.add(i);return out;} }
